import{_ as o,C as s,o as a,c as i,j as t,a as r,E as h,ak as c}from"./chunks/framework.sV-XtlWr.js";const y=JSON.parse('{"title":"Extension connection","description":"Connect Piwi Picker to your Piwi instance in one step, and keep the URL patterns that tell it which project a page belongs to on the instance, shared by your team.","frontmatter":{"title":"Extension connection","description":"Connect Piwi Picker to your Piwi instance in one step, and keep the URL patterns that tell it which project a page belongs to on the instance, shared by your team.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/extension-connection.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/extension-connection.html"}],["meta",{"property":"og:title","content":"Extension connection | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Connect Piwi Picker to your Piwi instance in one step, and keep the URL patterns that tell it which project a page belongs to on the instance, shared by your team."}]]},"headers":[],"relativePath":"features/extension-connection.md","filePath":"features/extension-connection.md","lastUpdated":1790836807000}'),d={name:"features/extension-connection.md"};function p(l,e,g,u,w,m){const n=s("Needs");return a(),i("div",null,[e[0]||(e[0]=t("h1",{id:"extension-connection",tabindex:"-1"},[r("Extension connection "),t("a",{class:"header-anchor",href:"#extension-connection","aria-label":'Permalink to "Extension connection"'},"​")],-1)),h(n,{extension:""}),e[1]||(e[1]=c('<p><a href="./extension.html">Piwi Picker</a> works on its own. Connected to your Piwi instance, it also matches a recording against your project&#39;s <a href="./test-functions.html">test functions</a> and shows <a href="./tested-elements.html">Tested elements</a>. Connecting takes one click, and the URL patterns that say which project a page belongs to live on the instance, so a team sets them once.</p><h2 id="connect-in-one-step" tabindex="-1">Connect in one step <a class="header-anchor" href="#connect-in-one-step" aria-label="Permalink to &quot;Connect in one step&quot;">​</a></h2><ol><li>Open Piwi Picker&#39;s settings (the gear button in its popup) and type your instance&#39;s address.</li><li>Click <strong>Connect</strong>. The browser asks to let Piwi Picker reach that one address; allow it.</li><li>A tab opens on your instance. Sign in if asked, with a password or your usual sign-in provider: you come back to the same page. It names the connecting browser (&quot;Piwi Picker in Chrome on Windows&quot;) and shows a code.</li><li>Check that the settings page shows the same code, tick <strong>My Piwi Picker shows this same code</strong>, then click <strong>Allow</strong>. The link carries the code, so anyone could send you one: if you did not just click <strong>Connect</strong>, deny.</li></ol><p>The tab closes, the settings say <strong>Connected as</strong> your name, and the instance&#39;s URL patterns appear under <strong>From your Piwi instance</strong>.</p><p>Allowing creates an API key for your account, named after the browser, with your role and project access. It is listed with your other keys in your account&#39;s API key settings, where you revoke it; the browser is then disconnected at its next request. <strong>Deny</strong>, or ten minutes without an answer, creates nothing.</p><p>With <a href="/operate/authentication.html">authentication</a> off, <strong>Allow</strong> only confirms the connection: there is no account to own a key, and none is needed.</p><h3 id="use-an-api-key-instead" tabindex="-1">Use an API key instead <a class="header-anchor" href="#use-an-api-key-instead" aria-label="Permalink to &quot;Use an API key instead&quot;">​</a></h3><p>Under <strong>Use an API key instead</strong>, paste a key created in your account&#39;s <a href="/operate/api-keys.html">API key settings</a> and click <strong>Save and test</strong>. An instance older than the one-step connection needs this. So does the desktop app, whose server answers only requests carrying its access token.</p><h2 id="url-patterns" tabindex="-1">URL patterns <a class="header-anchor" href="#url-patterns" aria-label="Permalink to &quot;URL patterns&quot;">​</a></h2><p>A URL pattern is a glob over a page&#39;s whole address: <code>*</code> matches within one part of the path, <code>**</code> across parts. So <code>https://staging.shop.example/**</code> covers every page of that site, and <code>https://shop.example/admin/*</code> the pages one level under <code>/admin</code>. A pattern starts with <code>http://</code>, <code>https://</code> or a wildcard.</p><p>Each project keeps its own list in its <strong>Settings</strong> tab, under <strong>Browser extension URLs</strong>. A pattern can name:</p><ul><li>an <strong>environment</strong>, a label shown beside the project in Piwi Picker (<code>staging</code>, <code>production</code>);</li><li>a <strong>branch</strong>, the one deployed at those addresses, whose tests <a href="./tested-elements.html">Tested elements</a> shows;</li><li>a <strong>path prefix</strong>, the part of the path your site serves its pages under and the tests did not: <code>/app</code> when the site serves <code>/app/checkout</code> and the tests ran at <code>/checkout</code>. Piwi Picker removes it before comparing the page with the <a href="./tested-elements.html#this-page">pages the tests ran on</a>, whole parts only (<code>/application</code> keeps its path), and a bug report sent from the site keys its page without it. It is a plain path of at most four parts, with no query, hash or wildcard;</li><li>a <strong>tests&#39; path prefix</strong>, the reverse: the part of the path the tests ran the pages under and the site does not, <code>/app</code> when the tests ran <code>/app/checkout</code> and the site serves <code>/checkout</code>. Piwi Picker puts it in front of the page&#39;s path; the site&#39;s root becomes <code>/app</code>. With both set, the one replaces the other (<code>/app</code> on the site, <code>/v2</code> in the tests), and a page outside the path prefix is left as it is.</li></ul><p>The editor suggests one pattern per site your suite already visited: the <code>baseURL</code> of recent runs, the full addresses its tests opened with <code>page.goto</code> in runs whose Playwright config sets no <code>baseURL</code>, the pages of the <a href="./scenario-gaps.html">Test Map</a> and the absolute pages its locators ran on. A site a run visited comes with the environment the run was reported with (the <a href="/guide/reporter.html">reporter</a>&#39;s <code>environment</code> option or <code>PIWI_ENVIRONMENT</code>), and the suggestions are grouped by it. The newest few runs of every environment are read, so a nightly production suite is suggested beside a staging one that runs on every push. <strong>Add</strong> puts a suggestion in the list with its environment, <strong>Add all</strong> every suggestion of that environment; <strong>Save patterns</strong> stores them. When there is nothing to suggest, the editor says why: every site already has a pattern, or no recent run recorded a <code>baseURL</code> or opened a full address. Editing the list takes the administrator role, like the rest of the project&#39;s settings.</p><h3 id="which-project-applies" tabindex="-1">Which project applies <a class="header-anchor" href="#which-project-applies" aria-label="Permalink to &quot;Which project applies&quot;">​</a></h3><p>Piwi Picker reads the patterns of every project you can see when it connects and each time its settings open, and keeps a copy, so a page&#39;s project is known with the instance out of reach. For a page it decides in this order:</p><ol><li>the project chosen in the popup&#39;s <strong>Active project</strong>, for the rest of the browser session;</li><li>the patterns under <strong>This browser only</strong>, the first that matches;</li><li>the instance&#39;s patterns, by project, in each project&#39;s order, the first that matches.</li></ol><p>A pattern kept in the browser is therefore an override for that browser alone. The settings page marks each pattern with where it comes from.</p><h3 id="add-a-site" tabindex="-1">Add a site <a class="header-anchor" href="#add-a-site" aria-label="Permalink to &quot;Add a site&quot;">​</a></h3><p>When the current tab matches no pattern, the popup says so and offers <strong>Add this site</strong>. It opens the settings with <code>https://&lt;site&gt;/**</code> filled in: choose a project and click <strong>Add to Piwi</strong>, or <strong>Keep in this browser only</strong>. Adding to the instance takes a role that edits the project; without one, the settings say so and keep the second choice.</p><h2 id="what-is-sent" tabindex="-1">What is sent <a class="header-anchor" href="#what-is-sent" aria-label="Permalink to &quot;What is sent&quot;">​</a></h2><p>Connecting sends the browser&#39;s and the operating system&#39;s names, nothing else about the machine. Afterwards the extension downloads the URL patterns, each mapped project&#39;s function catalog and its locator index; adding a site sends that one pattern. A recording is never sent to the instance: <strong>Send to editor</strong> sends it only to an editor paired on the same computer. A bug report is sent only from <strong>Send to Piwi…</strong>, after a preview of exactly what goes (see <a href="./bug-reports.html">Bug reports</a>). Only the settings page and the extension&#39;s background worker talk to the instance or the editor, never a script running in a page.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./extension.html">Browser extension</a>: everything Piwi Picker does, with or without a connection</li><li><a href="/operate/api-keys.html">API keys</a>: create, list and revoke keys, those Piwi Picker created included</li><li><a href="./tested-elements.html">Tested elements</a>: what a connection shows on the page</li><li><a href="/operate/project-access.html">Project access</a>: which projects, and so which patterns, a user sees</li></ul>',23))])}const k=o(d,[["render",p]]);export{y as __pageData,k as default};
